export default function step({ phase, baseUrl, owner, state, response }) {
  const enc = (x) => encodeURIComponent(x);
  let s = { ...(state || {}) };
  if (phase === "start") {
    if (!baseUrl.startsWith("https://") || !owner || owner.startsWith("YOUR_"))
      throw Error("Configure HTTPS Wekan URL and owner");
    s = { base: baseUrl.replace(/\/+$/, ""), owner };
    return {
      state: s,
      url: s.base + "/api/boards",
      body: { title: "Documentation", owner },
      result: s,
    };
  }
  const root = s.base + "/api/boards/";
  if (phase === "board") {
    if (!response?._id) throw Error("Board ID missing");
    s.board = response._id;
    return { state: s, url: root + enc(s.board) + "/lists", body: { title: "To Do" }, result: s };
  }
  if (phase === "todo") {
    if (!response?._id) throw Error("To Do list ID missing");
    s.todo = response._id;
    return { state: s, url: root + enc(s.board) + "/lists", body: { title: "Done" }, result: s };
  }
  if (phase === "done") {
    if (!response?._id) throw Error("Done list ID missing");
    s.done = response._id;
    return { state: s, url: root + enc(s.board) + "/swimlanes", body: {}, result: s };
  }
  if (phase === "swim") {
    if (!Array.isArray(response) || response.length !== 1 || !response[0]?._id)
      throw Error("Expected one swimlane in the new board");
    s.swimlane = response[0]._id;
    return {
      state: s,
      url: root + enc(s.board) + "/lists/" + enc(s.todo) + "/cards",
      body: { title: "Document Wekan node", authorId: s.owner, swimlaneId: s.swimlane },
      result: s,
    };
  }
  if (phase === "card") {
    if (!response?._id) throw Error("Card ID missing");
    s.card = response._id;
    return {
      state: s,
      url: root + enc(s.board) + "/lists/" + enc(s.todo) + "/cards/" + enc(s.card),
      body: { listId: s.done },
      result: s,
    };
  }
  if (phase === "move") {
    return {
      state: s,
      url: root + enc(s.board) + "/lists/" + enc(s.done) + "/cards/" + enc(s.card),
      body: {},
      result: s,
    };
  }
  if (phase === "confirm") {
    if (response?._id !== s.card || response?.listId !== s.done)
      throw Error("Moved card not confirmed");
    return { state: s, url: "", body: {}, result: s };
  }
  throw Error("Unknown phase");
}

